/// Request to create a training job.
pub const TrainingJobCreate = struct {
    /// GLiNER only. Opt-in: when true, downsample each training dataset to min(max_samples_per_dataset, max(min_samples_per_dataset, samples_per_label * num_labels)). When omitted or false, the full provided dataset is used without downsampling.
    auto_data_sizing: ?std.json.Value = null,
    /// Trainable model ID from GET /v1/base-models?supports_training=true (e.g. 'fastino/gliner2-base-v1').
    base_model: []const u8,
    /// Training batch size (1 to 256). Prefer omitting this field so the training service applies the catalog default for ``base_model``. GLiNER encoder batches that do not fit the training GPU are reduced to the largest that fits. For decoder models, explicit values equal to this Field default (4) that exceed the model's safe maximum are treated as legacy unset clients and clamped to the catalog default; any other oversize value is rejected.
    batch_size: ?i64 = null,
    /// Datasets to train on (supports multi-dataset training)
    datasets: []const DatasetReference,
    /// Minimum validation loss improvement to count as progress. Prevents early stopping from triggering on noise.
    early_stopping_min_delta: ?f64 = null,
    /// Validation epochs without improvement before stopping. Requires validation_data_percentage > 0. Set to 0 to disable.
    early_stopping_patience: ?i64 = null,
    /// GLiNER only: learning rate applied to encoder parameters. When omitted, falls back to `learning_rate`.
    encoder_learning_rate: ?std.json.Value = null,
    /// GLiNER2 (encoder) only: run periodic mid-training validation every N optimizer steps, in requested-batch units like save_steps (scaled by the same ratio when GPU admission reduces the batch). When omitted, validation runs only at each epoch end — the standard cadence. Periodic evals are for cost/visibility (loss curve, W&B): they do NOT select the deployed checkpoint. Checkpoint selection uses the full-split epoch-end and final validation. Checkpoint saving still follows save_steps independently.
    eval_steps: ?std.json.Value = null,
    /// Accumulate gradients over N mini-batches before each optimizer step. Effective batch size = batch_size * N. Honoured by GLiNER and dense decoder LoRA training; when omitted, dense LoRA applies the per-model catalog default (8 for the H200 Nemotron 3.5 profiles, whose per-device batch is pinned to 1).
    gradient_accumulation_steps: ?std.json.Value = null,
    /// GLiNER2 only: how training samples each row's label prompt. 'stochastic' (used when omitted) keeps the GLiNER2 library's augmentation: it randomly drops classification labels, sometimes the true one, renames labels to placeholders such as 'label 1' or 'entity 1', and shuffles their order. 'off' trains every entity and classification task on its full declared label set, in order, under its real names: suited to a fixed label set. It also stops renaming JSON-structure fields to placeholders (the library shares that setting); structure and field dropping, relations and task order keep their sampling. Validation is never sampled.
    label_sampling: ?std.json.Value = null,
    /// Peak learning rate for AdamW. When omitted, the trainer's default applies — the per-model catalog rate (2e-4) for decoder LoRA on Modal, 2e-5 elsewhere. Pinning the old 2e-5 default on a decoder LoRA run under-trains the adapter by an order of magnitude.
    learning_rate: ?std.json.Value = null,
    /// LoRA alpha. When omitted, the trainer's default applies: the per-model catalog alpha for decoder LoRA on Modal, or 32 elsewhere.
    lora_alpha: ?std.json.Value = null,
    /// LoRA dropout. When omitted, the trainer's default applies: the per-model catalog dropout for decoder LoRA on Modal, or 0.1 elsewhere.
    lora_dropout: ?std.json.Value = null,
